/// Update the listing for a game server and renew its registration lease
///
/// A successful authenticated update also counts as a heartbeat, advancing `last_heartbeat` and `refresh_before`. Rejected updates do not renew the lease.
///
/// # Errors
/// Returns a transport, decoding, or declared HTTP error.
pub async fn update(
    configuration: &configuration::Configuration,
    x_chiv2_server_browser_key: &str,
    server_id: &str,
    update_registered_server: models::UpdateRegisteredServer,
) -> Result<models::UpdateResponse, Error<UpdateError>> {
    let p_header_x_chiv2_server_browser_key = x_chiv2_server_browser_key;
    let p_path_server_id = server_id;
    let p_body_update_registered_server = update_registered_server;
    let uri_str = format!(
        "{}/api/v1/servers/{server_id}",
        configuration.base_path,
        server_id = crate::apis::urlencode(p_path_server_id)
    );
    let mut req_builder = configuration.client.request(reqwest::Method::PUT, &uri_str);
    if let Some(ref user_agent) = configuration.user_agent {
        req_builder = req_builder.header(reqwest::header::USER_AGENT, user_agent.clone());
    }
    req_builder = req_builder.header(
        "X-CHIV2-SERVER-BROWSER-KEY",
        p_header_x_chiv2_server_browser_key.to_string(),
    );
    req_builder = req_builder.json(&p_body_update_registered_server);
    let req = req_builder.build()?;
    let resp = configuration.client.execute(req).await?;
    let status = resp.status();
    let content_type = resp
        .headers()
        .get("content-type")
        .and_then(|value| value.to_str().ok())
        .unwrap_or("application/octet-stream");
    let content_type = ContentType::from(content_type);
    let content = resp.text().await?;

    if !status.is_client_error() && !status.is_server_error() {
        match content_type {
            ContentType::Json => serde_json::from_str(&content).map_err(Error::from),
            ContentType::Text => Err(Error::from(serde_json::Error::custom("Received `text/plain` content type response that cannot be converted to `models::UpdateResponse`"))),
            ContentType::Unsupported(unknown_type) => Err(Error::from(serde_json::Error::custom(format!("Received `{unknown_type}` content type response that cannot be converted to `models::UpdateResponse`")))),
        }
    } else {
        let entity = {
            if status.as_u16() == 401 {
                serde_json::from_str(&content)
                    .ok()
                    .map(UpdateError::Status401)
            } else if status.as_u16() == 400 {
                serde_json::from_str(&content)
                    .ok()
                    .map(UpdateError::Status400)
            } else if status.as_u16() == 403 {
                serde_json::from_str(&content)
                    .ok()
                    .map(UpdateError::Status403)
            } else if status.as_u16() == 404 {
                serde_json::from_str(&content)
                    .ok()
                    .map(UpdateError::Status404)
            } else {
                serde_json::from_str(&content)
                    .map(UpdateError::DefaultResponse)
                    .or_else(|_| serde_json::from_str(&content).map(UpdateError::UnknownValue))
                    .ok()
            }
        };
        Err(Error::ResponseError(Box::new(ResponseContent {
            status,
            content,
            entity,
        })))
    }
}
